head.script:
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 브라우저에서 두번째 inputCalendar 에서 1월달을 선택한다.
    //1. In the browser, select January in the second inputCalendar.
    //Verify step 1. In the second inputCalendar in the browser, it is displayed as a Red font with a holiday on January 1.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar2_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar2_calendar_selectbox_year_button').click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar2_calendar_selectbox_year_itemTable_38').click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar2_calendar_selectbox_month_button').click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar2_calendar_selectbox_month_itemTable_0').click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //mobile
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar2_calendar').gotoYear(2016)");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar2_calendar').gotoMonth(1)");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#inputCalendar2_calendar_cell_0_5').hasClass('w2calendar_holiday')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 02-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
